using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"GetTypeInfo<WeatherForecast> → Type = {typedInfo.Type.Name}");

// Use the typed metadata to serialize
var forecast = new WeatherForecast("Seattle", 62);
string json = JsonSerializer.Serialize(forecast, typedInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// 2a. Type the default resolver *can* handle → returns true
if (options.TryGetTypeInfo<WeatherForecast>(out var info))
    Console.WriteLine($"TryGetTypeInfo<WeatherForecast> → found ({info!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<WeatherForecast> → not found");

// 2b. Build options with an empty custom resolver so the type is NOT available
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers = { (ti) =>
        {
            // Strip every type except string
            if (ti.Type != typeof(string))
                ti.Properties.Clear();
        }}
    }
};

// The resolver still technically resolves the type, so let's use a truly
// empty resolver to show a "not found" branch.
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // no resolvers → nothing resolved
};

if (empty.TryGetTypeInfo<WeatherForecast>(out var missing))
    Console.WriteLine($"TryGetTypeInfo on empty resolver → found ({missing!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo on empty resolver → not found (no exception thrown!)");

// --- Done ---
public record WeatherForecast(string City, int TempF);

